// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *IssuedReminderLine) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, IssuedReminderLineTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (reminder_no, line_no)`,
		fmt.Sprintf("%s$Issued_Reminder_Line$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (reminder_no, type)`,
		fmt.Sprintf("%s$Issued_Reminder_Line$type", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index type: %w", err)
	}
	var keys []sift.Key
	for _, spec := range issuedReminderLineSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, IssuedReminderLineTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, IssuedReminderLineTableName, keys)
}

// issuedReminderLineSIFTSpecs are the table's keys with sum_index_fields
func issuedReminderLineSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *IssuedReminderLine) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, IssuedReminderLineTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range issuedReminderLineSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, IssuedReminderLineTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: IssuedReminderLineTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, IssuedReminderLineTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

